-- T140 (the full review of 2026-10-24 on ecb0388, W15 and W16; the owner's decisions of 2026-10-29
-- and 2026-10-31): the database refuses what the ERD forbids. Generated by `prisma migrate diff
-- --from-config-datasource --to-schema prisma/schema --script` against a database holding every
-- migration before it, then extended by hand for the checks the schema language cannot say
-- (specs/003-booking/data-model.md §2.1 and §5; ERD §15 rules 28, 29 and 36 to 38, §14).
--
-- Phase 2 writes `packages`, `availability_slots` and `sessions` first, so the limits land before
-- their writers. No row of either database broke a check when this was written (checked
-- 2026-11-01), so each constraint is added validated.

-- CreateIndex
CREATE INDEX "user_sessions_previous_refresh_token_hash_idx" ON "user_sessions"("previous_refresh_token_hash");

-- Hand-written: what the schema language cannot say.

-- Rule 36: a package has one session or more, a price above zero, and sessions of 30, 45 or 60
-- minutes (FR-PROFILE-2 as amended 2026-10-31, FR-311).
ALTER TABLE "packages" ADD CONSTRAINT "packages_session_count_positive_check"
    CHECK ("session_count" >= 1);

ALTER TABLE "packages" ADD CONSTRAINT "packages_price_positive_check"
    CHECK ("price_piasters" > 0);

ALTER TABLE "packages" ADD CONSTRAINT "packages_session_duration_allowed_check"
    CHECK ("session_duration_minutes" IN (30, 45, 60));

-- Rule 37: a weekly slot falls on a day 0 (Sunday) to 6 (Saturday), as Postgres `EXTRACT(DOW)`
-- counts, and lasts 30, 45 or 60 minutes (FR-PROFILE-4 as amended 2026-10-31).
ALTER TABLE "availability_slots" ADD CONSTRAINT "availability_slots_day_of_week_range_check"
    CHECK ("day_of_week" BETWEEN 0 AND 6);

ALTER TABLE "availability_slots" ADD CONSTRAINT "availability_slots_duration_allowed_check"
    CHECK ("duration_minutes" IN (30, 45, 60));

-- Rule 38: a session of an enrollment is numbered from 1.
ALTER TABLE "sessions" ADD CONSTRAINT "sessions_sequence_number_positive_check"
    CHECK ("sequence_number" >= 1);

-- Rule 28: a chain's generations are positioned from 1, the origin first.
ALTER TABLE "isnad_entries" ADD CONSTRAINT "isnad_entries_position_positive_check"
    CHECK ("position" >= 1);

-- Rule 29: an audit entry's target label is never empty. The 200-character bound stays
-- `audit_logs_target_label_check` (`20261018000500_audit_target_label`); the writer refuses an
-- empty label before the insert, and the database now refuses it again.
ALTER TABLE "audit_logs" ADD CONSTRAINT "audit_logs_target_label_not_empty_check"
    CHECK (char_length("target_label") > 0);
